import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;

interface Sink<T> {                          // no declaration-site variance in Java
    void accept(T item);
}

class Sinks {
    // every consumer parameter must remember ? super
    static <T> void feedAll(List<? extends T> items, Sink<? super T> sink) {
        for (T item : items) sink.accept(item);
    }

    static <T> T highest(List<? extends T> items, Comparator<? super T> order) {
        T best = items.get(0);
        for (T item : items) if (order.compare(item, best) > 0) best = item;
        return best;
    }

    static <E> void subscribe(Consumer<? super E> handler) { /* store it */ }
}

