interface Sink<in T> {                       // say it once
    fun accept(item: T)
}

// Sink and List carry their variance, so these signatures stay plain
fun <T> feedAll(items: List<T>, sink: Sink<T>) {
    for (item in items) sink.accept(item)
}

// java.util.Comparator is a Java interface: invariant, so project it here
fun <T> highest(items: List<T>, order: Comparator<in T>): T {
    var best = items[0]
    for (item in items) if (order.compare(item, best) > 0) best = item
    return best
}

